  inbox: 'Inbox', msg_one: 'mensahe', msg_many: 'mga mensahe', refresh: 'I-refresh ang inbox',
  empty_h: 'Naghihintay ng mga papasok na email…', empty_p: 'Aktibo ang iyong inbox. Magpadala ng email o OTP sa address sa itaas at awtomatiko itong lalabas dito.',
